const QR_SIZE = 25;

const qrPath = (() => {
    const finder = (x: number, y: number) => {
        const dx = x < 7 ? x : x - (QR_SIZE - 7);
        const dy = y < 7 ? y : y - (QR_SIZE - 7);
        const ring = Math.max(Math.abs(dx - 3), Math.abs(dy - 3));
        return ring !== 2;
    };
    const inFinder = (x: number, y: number) => (x < 8 && y < 8) || (x >= QR_SIZE - 8 && y < 8) || (x < 8 && y >= QR_SIZE - 8);
    let seed = 4120;
    const random = () => (seed = (seed * 16807) % 2147483647) / 2147483647;
    const cells: string[] = [];
    for (let y = 0; y < QR_SIZE; y++) {
        for (let x = 0; x < QR_SIZE; x++) {
            const corner = x < 7 || x >= QR_SIZE - 7 ? (y < 7 || (y >= QR_SIZE - 7 && x < 7)) : false;
            const dark = corner ? finder(x, y) : !inFinder(x, y) && (x === 6 || y === 6 ? (x + y) % 2 === 0 : random() < .48);
            if (dark) cells.push(`M${x} ${y}h1v1h-1z`);
        }
    }
    return cells.join('');
})();

const Icon: React.FC<{ name: IconName; size: number; className?: string }> = ({ name, size, className }) => (
    <svg className={className} width={size} height={size} viewBox="0 0 24 24" fill="currentColor" aria-hidden="true">
        <path d={ICONS[name]} />
    </svg>
);

const ScannerIcon: React.FC<{ paths: readonly string[] }> = ({ paths }) => (
    <svg width={35} height={35} viewBox="0 0 1000 1000" fill="currentColor" aria-hidden="true">
        {paths.map(d => <path d={d} key={d.slice(0, 16)} />)}
    </svg>
);

