export const CrmAppPhone: React.FC<{ data: TrackerCaseMockupLocale }> = ({ data }) => (
    <Phone app="crm" aria={data.aria.crmApp} clock={data.clock}>
        <div className="trkc-log">
            <div className="trkc-log__list">
                {data.crmApp.calls.map(call => (
                    <div className="trkc-log__card" key={call.date}>
                        <span className="trkc-log__text">
                            <span>{call.name}</span>
                            <span>{data.crmApp.numberLabel} {call.number}</span>
                            <span>{data.crmApp.dateLabel} {call.date}</span>
                        </span>
                        <span className="trkc-log__type"><Icon name={call.type} size={24} className={`is-${call.type}`} /></span>
                        <span className="trkc-log__call"><Icon name="call" size={24} /></span>
                    </div>
                ))}
            </div>
            <div className="trkc-log__actions">
                {(['star', 'info', 'settings'] as const).map(name => (
                    <span className="trkc-log__round" key={name}><Icon name={name} size={40} /></span>
                ))}
            </div>
        </div>
    </Phone>
);

